INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p791326-acct401', 'stk-user3328', 'ACCT 401', 'info', '{"desc": "حياك اخوي … الكورس كله حسابات والحفظ فيه قليل\nمن ناحية الكورس فصعوبته متوسطه\nلكن الكلام على مستر جيمس تيمونز … الاستاذ هذا جبار(اشتغل في mit وكم شركه عالميه والحين بأرامكو) وشرحه حلو ولاهو من الدكاتره اللي اذا ماعرف مسأله جاب حلها من المانيوال لأنه مرتين صعب عليه الحل ومع ذلك حلها\n\nعيوبه :\n- كوزاته مفاجئه … لكن بنفس الوقت سهله اذا كنت حاضر الكلاس اللي قبلها لأنها نفس المسأله اللي شرحها بس تغيير بالأرقام\n- تصحيحه سيء جدا جدا جدا ولازم تجيب الحل صح لأن نادرا يعطيك درجات على الخطوات وحاولنا نناقشه ولكن ماعنده فينا !\n\nبشكل عام أعطيه +c\n\nالأترام السابقه كان يدرسها هو وميرغني …\nلكن الحين على كلامه هو راح يدرس كل الكورس وأول ميرغني متساعد كثير مع الطلاب لكن الحين مدري عن تيمونز\n\nمن ناحية الفائده … فأنا عن نفسي استفدت منه رغم غيابي الكثير في كورسه\n\nالله يوفقك وأي أسئله حاضرين …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct401/103062/2", "user": "user3328", "ts": 1297781981000, "tid": 103062, "pn": 2}}', 1297781981000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
